INSERT OR IGNORE INTO `content_entries` (`type`,`slug`,`title`,`summary`,`body`,`category`,`image_url`,`status`,`published_at`,`updated_at`) VALUES
('post','small-tools-lasting-value','Small tools can have lasting value','A case for making focused software that solves one real problem exceptionally well.','The best small tools rarely announce their complexity. They meet a specific need, fit naturally into a person’s day and then quietly get out of the way.\n\n## Begin with the useful part\n\nIt is tempting to start a new project by listing everything it could become. A better place to begin is the smallest meaningful change it can make for someone.\n\n> Good editing is a form of generosity: less to learn, less to manage and more room for the thing that matters.\n\n## Clarity is part of the craft\n\nA clear product does not need to be plain or impersonal.','Making','','published',1784361600,1784361600),
('post','designing-calm-interfaces','Designing calm interfaces','Practical choices that help useful products feel quieter, clearer and more considerate.','Calm interfaces respect attention. They make the next action clear, reduce visual competition and allow the product’s purpose to lead.\n\n## Start with hierarchy\n\nA strong hierarchy helps people understand what matters without having to inspect every element.\n\n## Use motion with care\n\nAnimation should explain change, not create noise.','Design','','published',1780358400,1780358400),
('post','maps-need-a-point-of-view','Maps need a point of view','Why thoughtful editing matters as much as accurate data in a map-led story.','A useful map does more than place accurate marks on a surface. It helps someone understand why those marks matter.\n\n## Edit toward the story\n\nEvery layer, label and interaction should support the question the map is trying to answer.','Data & maps','','published',1775865600,1775865600),
('project','focus-frames','Focus Frames','A calm visual timer for shaping deep-work sessions without watching the clock.','## The challenge\n\nMost timers add urgency to work that already feels pressured.\n\n## The approach\n\nFocus Frames turns time into a quiet, visual container—with gentle transitions and no noisy dashboards.\n\n- Fast session presets\n- Distraction-free full-screen mode\n- Accessible colour and motion settings','Productivity app','','published',1786579200,1786579200),
('project','signal-garden','Signal Garden','A small connected display that turns live environmental data into ambient light.','## The challenge\n\nUseful environmental data often lives in dashboards nobody checks.\n\n## The approach\n\nSignal Garden makes that data glanceable, physical and expressive using a low-power display and simple sensors.','Electronics','','published',1786579200,1786579200),
('project','contour-stories','Contour Stories','Interactive map essays that make places, movement and change easier to understand.','## The challenge\n\nMaps are powerful, but complex map interfaces can bury the story.\n\n## The approach\n\nContour Stories combines focused narrative, restrained cartography and small interactive moments.','Data & maps','','published',1786579200,1786579200),
('project','build-small-tools','Build Small Tools','A practical course about designing and shipping useful software without unnecessary complexity.','## The challenge\n\nPeople with useful ideas often get stuck before a small project becomes real.\n\n## The approach\n\nThe course follows a complete, realistic build from deciding scope through launch and iteration.','Online course','','published',1786579200,1786579200);
